{"content": "const express = require('express');
const router = express.Router();
const bcrypt = require('bcrypt');
const path = require('path');
const { v4: uuidv4 } = require('uuid');
const multer = require('multer');
const { isAuthenticated } = require('./auth');

// Multer config for file uploads
const storage = multer.diskStorage({
    destination: (req, file, cb) => {
        if (file.fieldname === 'cover_image') {
            cb(null, path.join(__dirname, '../public/uploads/covers'));
        } else if (file.fieldname === 'book_file') {
            cb(null, path.join(__dirname, '../public/uploads/books'));
        } else {
            cb(null, path.join(__dirname, '../public/uploads'));
        }
    },
    filename: (req, file, cb) => {
        const ext = path.extname(file.originalname);
        cb(null, `${uuidv4()}${ext}`);
    }
});

const upload = multer({
    storage,
    limits: { fileSize: 50 * 1024 * 1024 }, // 50MB
    fileFilter: (req, file, cb) => {
        if (file.fieldname === 'cover_image') {
            if (!/\.(jpg|jpeg|png|gif|webp)$/i.test(file.originalname)) {
                return cb(new Error('Only image files are allowed for covers'));
            }
        } else if (file.fieldname === 'book_file') {
            if (!/\.(pdf|epub|mobi)$/i.test(file.originalname)) {
                return cb(new Error('Only PDF, ePub, and MOBI files are allowed'));
            }
        }
        cb(null, true);
    }
}).fields([
    { name: 'cover_image', maxCount: 1 },
    { name: 'book_file', maxCount: 1 }
]);

// Login page
router.get('/', (req, res) => {
    if (req.session && req.session.isAdmin) {
        return res.redirect('/admin/dashboard');
    }
    res.render('admin/login', { title: 'Admin Login', error: null });
});

// Login handler
router.post('/login', async (req, res) => {
    const db = require('../db/database');
    const { username, password } = req.body;

    if (!username || !password) {
        return res.render('admin/login', { title: 'Admin Login', error: 'Please provide username and password' });
    }

    try {
        const user = db.prepare('SELECT * FROM admin_users WHERE username = ?').get(username);

        if (!user || !bcrypt.compareSync(password, user.password_hash)) {
            return res.render('admin/login', { title: 'Admin Login', error: 'Invalid username or password' });
        }

        req.session.isAdmin = true;
        req.session.adminId = user.id;
        res.redirect('/admin/dashboard');
    } catch (err) {
        console.error('Login error:', err);
        res.render('admin/login', { title: 'Admin Login', error: 'An error occurred. Please try again.' });
    }
});

// Logout
router.get('/logout', (req, res) => {
    req.session.destroy();
    res.redirect('/admin');
});

router.post('/logout', (req, res) => {
    req.session.destroy();
    res.redirect('/admin');
});

// Dashboard
router.get('/dashboard', isAuthenticated, (req, res) => {
    const db = require('../db/database');

    const stats = {
        totalBooks: db.prepare('SELECT COUNT(*) as count FROM books').get().count,
        publishedBooks: db.prepare('SELECT COUNT(*) as count FROM books WHERE is_published = 1').get().count,
        totalSubscribers: db.prepare('SELECT COUNT(*) as count FROM subscribers WHERE is_active = 1').get().count,
        totalMessages: db.prepare('SELECT COUNT(*) as count FROM contacts').get().count,
        totalDownloads: db.prepare('SELECT SUM(download_count) as sum FROM books').get().sum || 0
    };

    const recentMessages = db.prepare(`
        SELECT * FROM contacts ORDER BY created_at DESC LIMIT 5
    `).all();

    const recentBooks = db.prepare(`
        SELECT * FROM books ORDER BY created_at DESC LIMIT 5
    `).all();

    res.render('admin/dashboard', {
        title: 'Dashboard',
        stats,
        recentMessages,
        recentBooks
    });
});

// Books management
router.get('/books', isAuthenticated, (req, res) => {
    const db = require('../db/database');
    const books = db.prepare('SELECT * FROM books ORDER BY created_at DESC').all();
    res.render('admin/books', { title: 'Manage Books', books });
});

// New book page
router.get('/books/new', isAuthenticated, (req, res) => {
    res.render('admin/book-form', { title: 'Add New Book', book: null, error: null });
});

// Edit book page
router.get('/books/edit/:id', isAuthenticated, (req, res) => {
    const db = require('../db/database');
    const book = db.prepare('SELECT * FROM books WHERE id = ?').get(req.params.id);

    if (!book) {
        return res.redirect('/admin/books');
    }

    res.render('admin/book-form', { title: 'Edit Book', book, error: null });
});

// Create book
router.post('/books', isAuthenticated, (req, res) => {
    const db = require('../db/database');
    upload(req, res, (err) => {
        if (err) {
            const books = db.prepare('SELECT * FROM books ORDER BY created_at DESC').all();
            return res.render('admin/books', { title: 'Manage Books', books, error: err.message });
        }

        const { title, description, author, price, is_free, is_published } = req.body;
        const cover_image = req.files?.cover_image?.[0]?.filename || null;
        const file_path = req.files?.book_file?.[0]?.filename || null;
        const file_format = req.files?.book_file?.[0]?.originalname.split('.').pop().toUpperCase() || null;

        if (!title) {
            return res.render('admin/book-form', { title: 'Add New Book', book: null, error: 'Title is required' });
        }

        try {
            db.prepare(`
                INSERT INTO books (title, description, author, cover_image, file_path, file_format, price, is_free, is_published)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            `).run(
                title,
                description || '',
                author || 'Jediah Akeredolu',
                cover_image,
                file_path,
                file_format,
                price || 0,
                is_free ? 1 : 0,
                is_published ? 1 : 0
            );

            res.redirect('/admin/books');
        } catch (err) {
            console.error('Create book error:', err);
            res.render('admin/book-form', { title: 'Add New Book', book: null, error: 'Failed to create book' });
        }
    });
});

// Update book
router.post('/books/:id', isAuthenticated, (req, res) => {
    const db = require('../db/database');
    const bookId = req.params.id;

    upload(req, res, (err) => {
        if (err) {
            const books = db.prepare('SELECT * FROM books ORDER BY created_at DESC').all();
            return res.render('admin/books', { title: 'Manage Books', books, error: err.message });
        }

        const { title, description, author, price, is_free, is_published } = req.body;
        const cover_image = req.files?.cover_image?.[0]?.filename;
        const file_path = req.files?.book_file?.[0]?.filename;
        const file_format = req.files?.book_file?.[0]?.originalname.split('.').pop().toUpperCase();

        if (!title) {
            const book = db.prepare('SELECT * FROM books WHERE id = ?').get(bookId);
            return res.render('admin/book-form', { title: 'Edit Book', book, error: 'Title is required' });
        }

        try {
            // Get existing book
            const existing = db.prepare('SELECT * FROM books WHERE id = ?').get(bookId);

            // Build update query
            let query = `UPDATE books SET title = ?, description = ?, author = ?, price = ?, is_free = ?, is_published = ?, updated_at = CURRENT_TIMESTAMP`;
            let params = [title, description || '', author || 'Jediah Akeredolu', price || 0, is_free ? 1 : 0, is_published ? 1 : 0];

            if (cover_image) {
                query += `, cover_image = ?`;
                params.push(cover_image);
            }
            if (file_path) {
                query += `, file_path = ?`;
                params.push(file_path);
            }
            if (file_format) {
                query += `, file_format = ?`;
                params.push(file_format);
            }

            query += ` WHERE id = ?`;
            params.push(bookId);

            db.prepare(query).run(...params);
            res.redirect('/admin/books');
        } catch (err) {
            console.error('Update book error:', err);
            const book = db.prepare('SELECT * FROM books WHERE id = ?').get(bookId);
            res.render('admin/book-form', { title: 'Edit Book', book, error: 'Failed to update book' });
        }
    });
});

// Delete book
router.post('/books/delete/:id', isAuthenticated, (req, res) => {
    const db = require('../db/database');

    try {
        db.prepare('DELETE FROM books WHERE id = ?').run(req.params.id);
        res.redirect('/admin/books');
    } catch (err) {
        console.error('Delete book error:', err);
        res.redirect('/admin/books');
    }
});

// Subscribers
router.get('/subscribers', isAuthenticated, (req, res) => {
    const db = require('../db/database');
    const subscribers = db.prepare(`
        SELECT * FROM subscribers ORDER BY subscribed_at DESC
    `).all();
    res.render('admin/subscribers', { title: 'Subscribers', subscribers });
});

// Delete subscriber
router.post('/subscribers/delete/:id', isAuthenticated, (req, res) => {
    const db = require('../db/database');
    db.prepare('DELETE FROM subscribers WHERE id = ?').run(req.params.id);
    res.redirect('/admin/subscribers');
});

// Messages
router.get('/messages', isAuthenticated, (req, res) => {
    const db = require('../db/database');
    const messages = db.prepare(`
        SELECT * FROM contacts ORDER BY created_at DESC
    `).all();
    res.render('admin/messages', { title: 'Messages', messages });
});

// Mark message as read
router.post('/messages/read/:id', isAuthenticated, (req, res) => {
    const db = require('../db/database');
    db.prepare('UPDATE contacts SET is_read = 1 WHERE id = ?').run(req.params.id);
    res.redirect('/admin/messages');
});

// Delete message
router.post('/messages/delete/:id', isAuthenticated, (req, res) => {
    const db = require('../db/database');
    db.prepare('DELETE FROM contacts WHERE id = ?').run(req.params.id);
    res.redirect('/admin/messages');
});

// Content editor
router.get('/content', isAuthenticated, (req, res) => {
    const db = require('../db/database');
    const dbContent = {};

    const sections = ['hero', 'about', 'offers', 'books', 'newsletter', 'contact', 'social'];
    const getContent = db.prepare('SELECT content FROM site_content WHERE section = ?');

    for (const section of sections) {
        const row = getContent.get(section);
        dbContent[section] = row ? JSON.parse(row.content) : {};
    }

    res.render('admin/content', { title: 'Edit Content', content: dbContent, error: null, success: null });
});

// Update content
router.post('/content', isAuthenticated, (req, res) => {
    const db = require('../db/database');
    const { section } = req.body;

    if (!section) {
        return res.redirect('/admin/content');
    }

    try {
        let content;

        switch (section) {
            case 'hero':
                content = {
                    tagline: req.body.tagline || '',
                    welcome: req.body.welcome || '',
                    description: req.body.description || ''
                };
                break;
            case 'about':
                content = {
                    title: req.body.title || '',
                    bio: req.body.bio || ''
                };
                break;
            case 'offers':
                content = {
                    title: req.body.title || '',
                    description: req.body.description || '',
                    features: [
                        { title: req.body.feature1_title || '', description: req.body.feature1_desc || '' },
                        { title: req.body.feature2_title || '', description: req.body.feature2_desc || '' },
                        { title: req.body.feature3_title || '', description: req.body.feature3_desc || '' }
                    ]
                };
                break;
            case 'books':
                content = {
                    title: req.body.title || '',
                    description: req.body.description || ''
                };
                break;
            case 'newsletter':
                content = {
                    title: req.body.title || '',
                    description: req.body.description || ''
                };
                break;
            case 'contact':
                content = {
                    title: req.body.title || '',
                    description: req.body.description || ''
                };
                break;
            case 'social':
                content = {
                    twitter: req.body.twitter || '',
                    instagram: req.body.instagram || '',
                    linkedin: req.body.linkedin || '',
                    facebook: req.body.facebook || ''
                };
                break;
            default:
                return res.redirect('/admin/content');
        }

        db.prepare(`
            INSERT OR REPLACE INTO site_content (section, content, updated_at)
            VALUES (?, ?, CURRENT_TIMESTAMP)
        `).run(section, JSON.stringify(content));

        // Refresh content for render
        const dbContent = {};
        const sections = ['hero', 'about', 'offers', 'books', 'newsletter', 'contact', 'social'];
        const getContent = db.prepare('SELECT content FROM site_content WHERE section = ?');

        for (const sec of sections) {
            const row = getContent.get(sec);
            dbContent[sec] = row ? JSON.parse(row.content) : {};
        }

        res.render('admin/content', { title: 'Edit Content', content: dbContent, error: null, success: 'Content updated successfully!' });
    } catch (err) {
        console.error('Update content error:', err);
        res.redirect('/admin/content');
    }
});

// Settings
router.get('/settings', isAuthenticated, (req, res) => {
    const db = require('../db/database');
    const settings = {};
    const rows = db.prepare('SELECT key, value FROM settings').all();
    for (const row of rows) {
        settings[row.key] = row.value;
    }
    res.render('admin/settings', { title: 'Settings', settings, error: null, success: null });
});

router.post('/settings', isAuthenticated, (req, res) => {
    const db = require('../db/database');
    const { site_name, site_description, contact_email, maintenance_mode } = req.body;

    try {
        const updateSetting = db.prepare(`
            INSERT OR REPLACE INTO settings (key, value, updated_at)
            VALUES (?, ?, CURRENT_TIMESTAMP)
        `);

        if (site_name) updateSetting.run('site_name', site_name);
        if (site_description) updateSetting.run('site_description', site_description);
        if (contact_email !== undefined) updateSetting.run('contact_email', contact_email);
        if (maintenance_mode !== undefined) updateSetting.run('maintenance_mode', maintenance_mode ? '1' : '0');

        const settings = {};
        const rows = db.prepare('SELECT key, value FROM settings').all();
        for (const row of rows) {
            settings[row.key] = row.value;
        }

        res.render('admin/settings', { title: 'Settings', settings, error: null, success: 'Settings saved successfully!' });
    } catch (err) {
        console.error('Save settings error:', err);
        const rows = db.prepare('SELECT key, value FROM settings').all();
        for (const row of rows) {
            settings[row.key] = row.value;
        }
        res.render('admin/settings', { title: 'Settings', settings, error: 'Failed to save settings', success: null });
    }
});

module.exports = router;
