{"content": "/**
 * JCROWN DIGITALS Setup Script
 * Run this after npm install to initialize the database and create admin user
 */

const sqlite3 = require('sqlite3').verbose();
const bcrypt = require('bcrypt');
const path = require('path');
const fs = require('fs');

console.log('JCROWN DIGITALS Setup');
console.log('=====================\n');

// Ensure upload directories exist
const dirs = [
    'public/uploads/covers',
    'public/uploads/books'
];

for (const dir of dirs) {
    const fullPath = path.join(__dirname, dir);
    if (!fs.existsSync(fullPath)) {
        fs.mkdirSync(fullPath, { recursive: true });
        console.log(`Created directory: ${dir}`);
    } else {
        console.log(`Directory exists: ${dir}`);
    }
}

// Database path
const dbPath = path.join(__dirname, 'db', 'jcrown.db');
const dbDir = path.dirname(dbPath);

if (!fs.existsSync(dbDir)) {
    fs.mkdirSync(dbDir, { recursive: true });
}

// Connect to database (creates file if doesn't exist)
const db = new sqlite3.Database(dbPath, (err) => {
    if (err) {
        console.error('Database connection error:', err);
        process.exit(1);
    }
    console.log('Database connected');
});

// Enable WAL mode
db.run('PRAGMA journal_mode = WAL');

// Create tables
db.exec(`
    CREATE TABLE IF NOT EXISTS admin_users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );

    CREATE TABLE IF NOT EXISTS books (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        description TEXT,
        author TEXT DEFAULT 'Jediah Akeredolu',
        cover_image TEXT,
        file_path TEXT,
        file_format TEXT,
        price REAL DEFAULT 0,
        is_free INTEGER DEFAULT 1,
        is_published INTEGER DEFAULT 0,
        download_count INTEGER DEFAULT 0,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );

    CREATE TABLE IF NOT EXISTS subscribers (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        email TEXT UNIQUE NOT NULL,
        is_active INTEGER DEFAULT 1,
        subscribed_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        unsubscribed_at DATETIME
    );

    CREATE TABLE IF NOT EXISTS contacts (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        email TEXT NOT NULL,
        subject TEXT,
        message TEXT NOT NULL,
        is_read INTEGER DEFAULT 0,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );

    CREATE TABLE IF NOT EXISTS site_content (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        section TEXT UNIQUE NOT NULL,
        content TEXT,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );

    CREATE TABLE IF NOT EXISTS settings (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        key TEXT UNIQUE NOT NULL,
        value TEXT,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
`, (err) => {
    if (err) console.error('Table creation error:', err);
    else console.log('Tables created');
});

// Create default admin user
db.get('SELECT COUNT(*) as count FROM admin_users', (err, row) => {
    if (err) {
        console.error('Error checking admin:', err);
    } else if (row.count === 0) {
        const defaultUsername = process.env.ADMIN_USERNAME || 'admin';
        const defaultPassword = process.env.ADMIN_PASSWORD || 'jcrown2024';
        const passwordHash = bcrypt.hashSync(defaultPassword, 12);

        db.run('INSERT INTO admin_users (username, password_hash) VALUES (?, ?)', [defaultUsername, passwordHash], (err) => {
            if (err) console.error('Error creating admin:', err);
            else {
                console.log('\nDefault admin user created:');
                console.log(`  Username: ${defaultUsername}`);
                console.log(`  Password: ${defaultPassword}`);
                console.log('  (Change these in production!)');
            }
        });
    } else {
        console.log('\nAdmin user already exists, skipping...');
    }
});

// Create default site content
db.get('SELECT COUNT(*) as count FROM site_content', (err, row) => {
    if (err) {
        console.error('Error checking content:', err);
    } else if (row.count === 0) {
        const defaultContent = {
            hero: {
                tagline: 'JCROWN DIGITALS',
                welcome: 'Welcome to the World of Jediah Akeredolu',
                description: 'Discover my world of ideas, digital publications, and resources created to share knowledge, inspire growth, and make useful information accessible.'
            },
            about: {
                title: 'Meet Jediah Akeredolu',
                bio: 'Jediah Akeredolu is the person behind JCROWN DIGITALS, a digital platform created to share ideas, publications, and valuable resources with readers. Through his work, he aims to make knowledge easier to access and give people an opportunity to discover useful perspectives and information through digital content.\n\nJCROWN DIGITALS represents his commitment to bringing his work together in one accessible space, where readers can explore his publications, discover available resources, and stay informed about new releases.\n\nWhether you are visiting to discover a book, explore a free resource, or learn more about his work, JCROWN DIGITALS is designed to make that experience simple, welcoming, and accessible.'
            },
            offers: {
                title: 'Knowledge Worth Discovering',
                description: 'Explore Jediah\'s digital books and access available resources through the website.',
                features: [
                    { title: 'Digital Publications', description: 'Explore books published by Jediah.' },
                    { title: 'Free Resources', description: 'Access publications and resources specifically made available for free.' },
                    { title: 'New Releases & Updates', description: 'Stay informed about new books and other updates.' }
                ]
            },
            books: {
                title: 'Explore & Download My Books',
                description: 'Discover the publications available through JCROWN DIGITALS. Choose a book to view its details and access the available download.'
            },
            newsletter: {
                title: 'Stay Connected with JCROWN DIGITALS',
                description: 'Get updates when new books, publications, and resources become available.'
            },
            contact: {
                title: 'Contact Jediah',
                description: 'Have a question or want to get in touch? Send me a message.'
            },
            social: {
                twitter: '',
                instagram: '',
                linkedin: '',
                facebook: ''
            }
        };

        const insertStmt = db.prepare('INSERT INTO site_content (section, content) VALUES (?, ?)');
        for (const [section, content] of Object.entries(defaultContent)) {
            insertStmt.run(section, JSON.stringify(content));
        }
        insertStmt.finalize();
        console.log('\nDefault site content created.');
    } else {
        console.log('\nSite content already exists, skipping...');
    }
});

// Create default settings
db.get('SELECT COUNT(*) as count FROM settings', (err, row) => {
    if (err) {
        console.error('Error checking settings:', err);
    } else if (row.count === 0) {
        const defaults = {
            site_name: 'JCROWN DIGITALS',
            site_description: 'Discover digital publications and resources by Jediah Akeredolu',
            contact_email: '',
            maintenance_mode: '0'
        };

        const insertStmt = db.prepare('INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)');
        for (const [key, value] of Object.entries(defaults)) {
            insertStmt.run(key, value);
        }
        insertStmt.finalize();
        console.log('Default settings created.');
    } else {
        console.log('Settings already exist, skipping...');
    }
});

// Close database and finish
setTimeout(() => {
    db.close((err) => {
        if (err) console.error('Error closing database:', err);
        else {
            console.log('\n=====================');
            console.log('Setup complete!');
            console.log('\nRun "npm start" to launch the server.');
            console.log('Admin panel: http://localhost:3000/admin');
        }
    });
}, 1000);
